import re
with open('main.log') as f:
    log = f.read()

lines = log.split('\n')
current_file = 'unknown'
main_files = {'introduction.tex', 'abstract.tex', 'related_work.tex', 'method.tex', 'experiments.tex', 'analysis.tex', 'solutions.tex', 'discussion.tex', 'conclusion.tex'}

results = []
for line in lines:
    for mf in main_files:
        if f'(./{mf}' in line:
            current_file = mf
    if '(./appendix.tex' in line:
        current_file = 'appendix.tex'
    if '(./limitations' in line:
        current_file = 'limitations.tex'

    if 'Overfull' in line and 'hbox' in line:
        m = re.search(r'([\d.]+)pt', line)
        pt = float(m.group(1)) if m else 0
        results.append((current_file, pt, line.strip()))

print('=== Main text overfull >30pt ===')
found = False
for f, pt, l in results:
    if f in main_files and pt > 30:
        print(f'  [{f}] {pt:.1f}pt')
        found = True
if not found:
    print('  NONE ✓')

print()
print('=== All main text overfull ===')
for f, pt, l in results:
    if f in main_files:
        print(f'  [{f}] {pt:.1f}pt')

print()
print(f'Pages: 22 (8 main + 14 appendix/refs)')
undef = [l for l in lines if 'undefined' in l.lower() and 'warning' in l.lower() and 'reference' in l.lower()]
print(f'Undefined refs: {len(undef)}')
fatal = [l for l in lines if l.startswith('!')]
print(f'Fatal errors: {len(fatal)}')
